var producto = {};
var action = '';

$(document).on('click','.btn-add-stcok',async function(event){
    action = 'create';
    editar_inventario = false;
    var producto_id = $(this).attr('producto_id');
    producto = await getProducto(producto_id);
    await openAddStock(producto_id);
    $('.input-cantidad').val('');
});

$(document).on('click','.btn-edit-stcok',async function(event){
    action = 'edit';
    var producto_id = $(this).attr('producto_id');
    producto = await getProducto(producto_id);
    await openAddStock(producto_id);
});

$(document).on('click', '.btn-update-stock', function(event) {
    var producto_id = $(this).attr('producto_id');
    updateStock(producto_id);
});

function getProducto(producto_id){
    return new Promise((resolve, reject)=>{
        $.ajax({
            url:`/admon/productos/${producto_id}`,  // ← CORREGIDO
            method:'get',
            success:function(response){
               resolve(response);
            }
        });
    })
}

function openAddStock(producto_id){
    return new Promise((resolve, reject)=>{
        $.ajax({
            url:`/admon/stock/${producto_id}/edit`,  // ← CORREGIDO
            method:'get',
            success:function(response){
                $('#modalAgregar').html(response);
                $('#modalAddStock').modal('show');
                resolve(response);
            }
        })
    })
}

function updateStock() {
    var csrfToken = $('meta[name="csrf-token"]').attr('content');
    var cantidad = $('#formEdit .input-cantidad').val();
    var precio_entrada = $('#formEdit input[name=precio_entrada]').val();

    if(cantidad=='' || precio_entrada==''){
        Swal.fire({
            title: 'Advertencia',
            text: "Los datos son obligatorios",
            icon: 'warning',
            showCancelButton: false,
            confirmButtonColor: '#3085d6',
            cancelButtonColor: '#d33',
            confirmButtonText: 'Aceptar'
        }).then((result) => {});
        return false;
    }

    $.ajax({
        url: `/admon/stock/${producto.id}`,  // ← CORREGIDO
        method: 'put',
        data: {
            cantidad: cantidad,
            precio_entrada: precio_entrada,
            _token: csrfToken,
            action
        },
        success: function(response) {
            $('#modalAddStock').modal('hide');
            toastr.success('Inventario actualizado','Mensaje');
            setTimeout(()=>{ location.reload(); }, 1500);
        },
        error: function(xhr, status, error) {
            console.error(error);
            alert('Error al actualizar el stock');
        }
    });
}
